public class CajaView extends VerticalLayout {
 private final CajaService caja; private final SucursalService sucursales; private final UUID empresa;
 private final ComboBox<Sucursal> sucursal=new ComboBox<>("Sucursal"); private final Div contenido=new Div(); private final Button botonAbrir=new Button(new Icon(VaadinIcon.PLUS),e->abrir());
 private final DateTimeFormatter formatoHora=DateTimeFormatter.ofPattern("HH:mm:ss"); private int paginaCierres; private int paginaMovimientos;
 public CajaView(CajaService caja,SucursalService sucursales){this.caja=caja;this.sucursales=sucursales;TenantUserDetails u=AuthService.getAuthenticatedUser();empresa=u==null?null:u.getEmpresaId();setWidthFull();setPadding(false);contenido.setWidthFull();cabecera();principal();}
 private void cabecera(){H2 titulo=new H2("Cierre Caja");titulo.getStyle().set("margin-bottom","0");botonAbrir.setIcon(new Icon(VaadinIcon.PLUS));botonAbrir.setTooltipText("Abrir Caja");botonAbrir.addThemeVariants(ButtonVariant.LUMO_PRIMARY);botonAbrir.getStyle().set("background-color","#1976d2").set("color","#ffffff");List<Sucursal> disponibles=empresa==null?List.of():sucursales.listarActivas(empresa);sucursal.setItems(disponibles);sucursal.setItemLabelGenerator(Sucursal::getNombre);sucursal.setWidth("min(100%,360px)");sucursal.addValueChangeListener(e->principal());HorizontalLayout barra=new HorizontalLayout(titulo,botonAbrir);barra.setWidthFull();barra.setAlignItems(Alignment.CENTER);barra.setJustifyContentMode(JustifyContentMode.BETWEEN);add(barra,new Paragraph("Control de apertura, movimientos, arqueo y cierre."),sucursal,contenido);}
 private void principal(){botonAbrir.setVisible(true);contenido.removeAll();paginaCierres=0;contenido.add(historico());}
private void detalle(SesionCaja s){botonAbrir.setVisible(false);contenido.removeAll();paginaMovimientos=0;Button volver=new Button("Volver a Cierre Caja",e->principal());volver.addThemeVariants(ButtonVariant.LUMO_TERTIARY);HorizontalLayout regreso=new HorizontalLayout(volver);regreso.setWidthFull();regreso.setJustifyContentMode(JustifyContentMode.START);CajaService.Resumen r=caja.resumen(empresa,s.getId());Button cerrar=new Button("Cerrar caja",e->cerrar(s));cerrar.addThemeVariants(ButtonVariant.LUMO_ERROR);Sucursal b=s.getSucursal();HorizontalLayout top=new HorizontalLayout(new Div(new H3("Caja "+s.getNumero()),new Span("● ABIERTA · "+(b==null?"":b.getNombre()))),cerrar);top.setWidthFull();top.setJustifyContentMode(JustifyContentMode.BETWEEN);HorizontalLayout kpis=new HorizontalLayout(tarjeta("FONDO INICIAL",m(s.getFondoInicial())),tarjeta("INGRESOS",m(r.ingresos())),tarjeta("EGRESOS",m(r.egresos())),tarjeta("EFECTIVO ESPERADO",m(r.efectivoEsperado())));kpis.setWidthFull();kpis.getStyle().set("flex-wrap","wrap");Button ingreso=new Button("+ Ingreso",e->movimiento(s,true));Button egreso=new Button("- Egreso",e->movimiento(s,false));HorizontalLayout acciones=new HorizontalLayout(new H3("Movimientos"),ingreso,egreso);acciones.setWidthFull();Grid<MovimientoCaja> tabla=new Grid<>(MovimientoCaja.class,false);tabla.setWidthFull();tabla.addColumn(x->x.getCreadoEn()==null?"—":x.getCreadoEn().toLocalTime().format(formatoHora)).setHeader("Hora");tabla.addColumn(x->tipoEspanol(x.getTipo())).setHeader("Tipo");tabla.addColumn(MovimientoCaja::getConcepto).setHeader("Concepto").setFlexGrow(1);tabla.addColumn(MovimientoCaja::getMetodoPago).setHeader("Método");tabla.addColumn(x->"IN".equals(x.getDireccion())?m(x.getMonto()):"—").setHeader("Entrada");tabla.addColumn(x->"OUT".equals(x.getDireccion())?m(x.getMonto()):"—").setHeader("Salida");contenido.add(regreso,top,kpis,new H4("Resumen por método · Total cobrado "+m(r.totalCobrado())),new Span(resumenMetodos(r.porMetodo())),acciones,tablaConPaginacion(tabla,r.movimientos()));}
 private Component tablaConPaginacion(Grid<MovimientoCaja> tabla,List<MovimientoCaja> movimientos){ComboBox<Integer> tamanio=new ComboBox<>("Filas por página",List.of(5,10,25,50,100));tamanio.setValue(10);tamanio.setWidth("150px");Button anterior=new Button("‹ Anterior"),siguiente=new Button("Siguiente ›");Span estado=new Span();HorizontalLayout controles=new HorizontalLayout(tamanio,anterior,estado,siguiente);controles.setWidthFull();controles.setAlignItems(Alignment.CENTER);controles.setJustifyContentMode(JustifyContentMode.BETWEEN);VerticalLayout envoltura=new VerticalLayout(tabla,controles);envoltura.setWidthFull();envoltura.setPadding(false);Runnable refrescar=()->{int total=movimientos.size(),paginas=Math.max(1,(int)Math.ceil(total/(double)tamanio.getValue()));paginaMovimientos=Math.min(paginaMovimientos,paginas-1);int desde=Math.min(paginaMovimientos*tamanio.getValue(),total),hasta=Math.min(desde+tamanio.getValue(),total);tabla.setItems(movimientos.subList(desde,hasta));tabla.setAllRowsVisible(true);estado.setText(total==0?"Sin movimientos":"Página "+(paginaMovimientos+1)+" de "+paginas+" · "+total+" movimientos");anterior.setEnabled(paginaMovimientos>0);siguiente.setEnabled(paginaMovimientos<paginas-1);};anterior.addClickListener(e->{if(paginaMovimientos>0){paginaMovimientos--;refrescar.run();}});siguiente.addClickListener(e->{if(paginaMovimientos+1<(int)Math.ceil(movimientos.size()/(double)tamanio.getValue())){paginaMovimientos++;refrescar.run();}});tamanio.addValueChangeListener(e->{paginaMovimientos=0;refrescar.run();});refrescar.run();return envoltura;}
 private void abrir(){if(sucursal.getValue()==null){error(new IllegalArgumentException("Seleccione una sucursal."));return;}Dialog d=new Dialog();d.setHeaderTitle("Abrir turno de caja");ComboBox<Caja> cajaSeleccionada=new ComboBox<>("Caja *");List<Caja> autorizadas=caja.autorizadas(empresa,sucursal.getValue().getId());cajaSeleccionada.setItems(autorizadas);cajaSeleccionada.setItemLabelGenerator(c->c.getCodigo()+" · "+c.getNombre());if(autorizadas.size()==1)cajaSeleccionada.setValue(autorizadas.get(0));TextField monto=campo("Fondo inicial *");TextArea nota=new TextArea("Observación");FormLayout f=new FormLayout(cajaSeleccionada,monto,nota);Button ok=new Button(new Icon(VaadinIcon.PLUS),e->{try{if(cajaSeleccionada.getValue()==null)throw new IllegalArgumentException("Seleccione una caja.");caja.abrirEnCaja(empresa,sucursal.getValue().getId(),cajaSeleccionada.getValue().getId(),valorMonto(monto.getValue()),nota.getValue(),UUID.randomUUID().toString());d.close();principal();}catch(Exception x){error(x);}});ok.setTooltipText("Abrir Caja");ok.addThemeVariants(ButtonVariant.LUMO_PRIMARY);ok.getStyle().set("background-color","#16a34a").set("color","#ffffff");Button cancelar=new Button(new Icon(VaadinIcon.CLOSE_SMALL),e->d.close());cancelar.setTooltipText("Cancelar");cancelar.addThemeVariants(ButtonVariant.LUMO_TERTIARY);cancelar.getStyle().set("background-color","#e2e8f0").set("color","#1e293b");d.add(f);d.getFooter().add(ok,cancelar);d.open();}
private void movimiento(SesionCaja s,boolean esIngreso){Dialog d=new Dialog();d.setHeaderTitle(esIngreso?"Registrar ingreso":"Registrar egreso");TextField monto=campo("Monto *");ComboBox<String> metodo=new ComboBox<>("Método",List.of("EFECTIVO","TARJETA","TRANSFERENCIA","CHEQUE","OTRO"));metodo.setValue("EFECTIVO");TextField concepto=new TextField("Concepto *");TextArea nota=new TextArea("Nota");FormLayout f=new FormLayout(monto,metodo,concepto,nota);Button ok=new Button(new Icon(VaadinIcon.DISC),e->{try{if(esIngreso)caja.ingreso(empresa,s.getId(),valorMonto(monto.getValue()),metodo.getValue(),concepto.getValue(),nota.getValue(),UUID.randomUUID().toString());else caja.egreso(empresa,s.getId(),valorMonto(monto.getValue()),metodo.getValue(),concepto.getValue(),nota.getValue(),UUID.randomUUID().toString());d.close();detalle(s);}catch(Exception x){error(x);}});ok.setTooltipText("Guardar");ok.addThemeVariants(ButtonVariant.LUMO_SUCCESS);ok.getStyle().set("background-color","#16a34a").set("color","#ffffff");Button cancelar=new Button(new Icon(VaadinIcon.CLOSE_SMALL),e->d.close());cancelar.setTooltipText("Cancelar");cancelar.addThemeVariants(ButtonVariant.LUMO_TERTIARY);cancelar.getStyle().set("background-color","#e2e8f0").set("color","#1e293b");d.add(f);d.getFooter().add(ok,cancelar);d.open();}
private void cerrar(SesionCaja s){Dialog d=new Dialog();d.setHeaderTitle("Cerrar caja · "+s.getNumero());TextField contado=campo("Efectivo contado *");TextArea nota=new TextArea("Nota de cierre"),motivo=new TextArea("Justificación de diferencia");FormLayout f=new FormLayout(contado,nota,motivo);Button ok=new Button(new Icon(VaadinIcon.DISC),e->{try{SesionCaja cerrada=caja.cerrarIdempotente(empresa,s.getId(),valorMonto(contado.getValue()),nota.getValue(),motivo.getValue(),UUID.randomUUID().toString());byte[] pdf=caja.generarCierre(empresa,cerrada.getId());d.close();Dialog exito=new Dialog();exito.setHeaderTitle("Caja cerrada correctamente");exito.add(new Paragraph("El cierre fue registrado y el comprobante PDF está disponible."));StreamResource recurso=new StreamResource("cierre-caja-"+cerrada.getId()+".pdf",()->new ByteArrayInputStream(pdf));Anchor ver=new Anchor(recurso,"Ver comprobante PDF");ver.setTarget("_blank");exito.getFooter().add(ver,new Button("Volver a Cierre Caja",ev->{exito.close();principal();}));exito.open();}catch(Exception x){error(x);}});ok.setTooltipText("Confirmar cierre");ok.addThemeVariants(ButtonVariant.LUMO_SUCCESS);ok.getStyle().set("background-color","#16a34a").set("color","#ffffff");Button cancelar=new Button(new Icon(VaadinIcon.CLOSE_SMALL),e->{d.close();detalle(s);});cancelar.setTooltipText("Cancelar");cancelar.addThemeVariants(ButtonVariant.LUMO_TERTIARY);cancelar.getStyle().set("background-color","#e2e8f0").set("color","#1e293b");d.add(f);d.getFooter().add(ok,cancelar);d.open();}
private Component historico(){List<SesionCaja> turnos=caja.historial(empresa);DatePicker desde=new DatePicker("Desde"),hasta=new DatePicker("Hasta");ComboBox<String> filtroCaja=new ComboBox<>("Caja");filtroCaja.setItems(turnos.stream().map(s->s.getCaja()==null?s.getNumero():s.getCaja().getNombre()).distinct().sorted().toList());filtroCaja.setClearButtonVisible(true);Grid<SesionCaja> g=new Grid<>(SesionCaja.class,false);g.setWidthFull();g.addColumn(s->s.getCaja()==null?s.getNumero():s.getCaja().getNombre()).setHeader("Caja");g.addColumn(SesionCaja::getNumero).setHeader("Turno");g.addColumn(s->s.getAbiertoEn()==null?"—":s.getAbiertoEn().format(formatoHora)).setHeader("Apertura");g.addColumn(s->s.getCerradoEn()==null?"—":s.getCerradoEn().format(formatoHora)).setHeader("Cierre");g.addComponentColumn(s->{Span badge=new Span("OPEN".equals(s.getEstado())?"Abierta":"Cerrada");badge.getElement().getThemeList().add("badge");return badge;}).setHeader("Estado");g.addColumn(s->m(s.getDiferencia())).setHeader("Diferencia");g.addComponentColumn(s->{if("OPEN".equals(s.getEstado())){Button ver=new Button(VaadinIcon.EYE.create(),e->detalle(s));ver.setTooltipText("Ver movimientos");ver.addThemeVariants(ButtonVariant.LUMO_TERTIARY_INLINE);ver.getStyle().set("background","transparent").set("border","none").set("box-shadow","none").set("min-width","auto").set("padding","0");return ver;}Anchor pdf=new Anchor("/api/cash/"+s.getId()+"/close-report");pdf.setTarget("_blank");pdf.add(VaadinIcon.FILE_TEXT.create());pdf.getElement().setAttribute("title","Ver comprobante");pdf.getStyle().set("display","inline-flex").set("padding","0");return pdf;}).setHeader("Acciones");ComboBox<Integer> tamanio=new ComboBox<>("Filas por página",List.of(5,10,25,50,100));tamanio.setValue(25);tamanio.setWidth("150px");Button anterior=new Button("‹ Anterior"),siguiente=new Button("Siguiente ›");Span estado=new Span();HorizontalLayout controles=new HorizontalLayout(tamanio,anterior,estado,siguiente);controles.setWidthFull();controles.setAlignItems(Alignment.CENTER);controles.setJustifyContentMode(JustifyContentMode.BETWEEN);HorizontalLayout filtros=new HorizontalLayout(desde,hasta,filtroCaja);filtros.setWidthFull();filtros.getStyle().set("flex-wrap","wrap");VerticalLayout v=new VerticalLayout(new H4("Cajas y últimos turnos"),filtros,g,controles);v.setWidthFull();Runnable refrescar=()->{List<SesionCaja> filtrados=turnos.stream().filter(s->desde.getValue()==null||s.getAbiertoEn()!=null&&!s.getAbiertoEn().toLocalDate().isBefore(desde.getValue())).filter(s->hasta.getValue()==null||s.getAbiertoEn()!=null&&!s.getAbiertoEn().toLocalDate().isAfter(hasta.getValue())).filter(s->filtroCaja.getValue()==null||filtroCaja.getValue().isBlank()||filtroCaja.getValue().equals(s.getCaja()==null?s.getNumero():s.getCaja().getNombre())).toList();int total=filtrados.size(),paginas=Math.max(1,(int)Math.ceil(total/(double)tamanio.getValue()));paginaCierres=Math.min(paginaCierres,paginas-1);int inicio=Math.min(paginaCierres*tamanio.getValue(),total),fin=Math.min(inicio+tamanio.getValue(),total);g.setItems(filtrados.subList(inicio,fin));g.setAllRowsVisible(true);estado.setText(total==0?"Sin turnos":"Página "+(paginaCierres+1)+" de "+paginas+" · "+total+" turnos");anterior.setEnabled(paginaCierres>0);siguiente.setEnabled(paginaCierres<paginas-1);};anterior.addClickListener(e->{if(paginaCierres>0){paginaCierres--;refrescar.run();}});siguiente.addClickListener(e->{if(paginaCierres+1<(int)Math.ceil(turnos.size()/(double)tamanio.getValue())){paginaCierres++;refrescar.run();}});tamanio.addValueChangeListener(e->{paginaCierres=0;refrescar.run();});desde.addValueChangeListener(e->{paginaCierres=0;refrescar.run();});hasta.addValueChangeListener(e->{paginaCierres=0;refrescar.run();});filtroCaja.addValueChangeListener(e->{paginaCierres=0;refrescar.run();});refrescar.run();return v;}
 private String tipoEspanol(String tipo){if(tipo==null||tipo.isBlank())return "—";return switch(tipo){case "MANUAL_INCOME"->"Ingreso manual";case "MANUAL_EXPENSE"->"Egreso manual";case "PAYMENT"->"Cobro";case "REFUND"->"Devolución";default->tipo.replace('_',' ').toLowerCase(Locale.ROOT);};}
private Component tarjeta(String l,String v){Div d=new Div(new Span(l),new H3(v));d.setWidth("100%");d.getStyle().set("flex","1 1 220px").set("padding",".75rem 1rem").set("min-width","170px").set("box-sizing","border-box").set("background","var(--lumo-contrast-5pct)").set("border-radius","var(--lumo-border-radius-l)");return d;} private TextField campo(String l){TextField f=new TextField(l);f.setPrefixComponent(new Span("RD$"));f.setPlaceholder("0.00");f.addBlurListener(e->{try{if(f.getValue()!=null&&!f.getValue().isBlank())f.setValue(formatoCampo(valorMonto(f.getValue())));}catch(NumberFormatException ignored){}});return f;} private BigDecimal valorMonto(String valor){return FormatoMonto.parse(valor);} private String formatoCampo(BigDecimal valor){return FormatoMonto.format(valor);} private String m(BigDecimal x){NumberFormat f=NumberFormat.getNumberInstance(Locale.US);f.setMinimumFractionDigits(2);f.setMaximumFractionDigits(2);return "RD$ "+f.format(x==null?BigDecimal.ZERO:x);} private String resumenMetodos(Map<String,BigDecimal> x){return x.isEmpty()?"Sin cobros registrados.":x.entrySet().stream().map(e->e.getKey()+": "+m(e.getValue())).reduce((a,b)->a+"  ·  "+b).orElse("");} private void error(Exception x){Notification.show(x.getMessage()==null?"No se pudo completar la operación.":x.getMessage(),5000,Notification.Position.MIDDLE);}
}
